// Text pools: game texts stored in 16KB mapper segments (generated by tools/mkdata.js).
// The reader is resident code; it maps a pool into page 2 only while copying a record and
// then restores the previous page-2 segment, so it can be called from overlay code.
#pragma once
#include "msxgl.h"

#define TXT_MAXPOOLS 12

// Loads TXT.IDX and TXT<n>.BIN from the current directory into freshly allocated mapper segments.
// Returns false on any failure (missing file, no free segment).
bool TextPool_Load();

// Copies record `id` (global id = TK_x + pointer, see textdef.h) to dst, 0-terminated.
// Returns its length, or 0 with dst = "" if the record does not exist.
// dst must not be in page 2 and must hold the longest record + 1 byte.
u16 TextPool_Read(u16 id, char* dst);
